import{_ as t,m as a,k as o,ah as n}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/resources/faq.md","filePath":"src/fr/developers/resources/faq.md"}'),r={name:"fr/developers/resources/faq.md"};function i(s,e,u,c,l,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Questions fréquentes sur le développement de templates Creopse. Pour une question non couverte ici, consultez le reste de la <a href="./../getting-started/introduction.html">documentation développeur</a> ou <a href="https://github.com/creopse/creopse/issues" target="_blank" rel="noreferrer">signalez un bug</a>.</p><h2 id="sections-widgets" tabindex="-1">Sections &amp; Widgets <a class="header-anchor" href="#sections-widgets" aria-label="Permalink to &quot;Sections &amp; Widgets&quot;">​</a></h2><h3 id="mon-bouton-cta-ne-mene-nulle-part-pourquoi" tabindex="-1">Mon bouton CTA ne mène nulle part, pourquoi ? <a class="header-anchor" href="#mon-bouton-cta-ne-mene-nulle-part-pourquoi" aria-label="Permalink to &quot;Mon bouton CTA ne mène nulle part, pourquoi ?&quot;">​</a></h3><p>Si le champ est de type <code>menu-item-link</code>, le <code>href</code> doit être résolu via <code>getLinkFromMenuItemId(champ)</code> et la navigation gérée via <code>openLink(champ)</code> — jamais un <code>href</code> brut sur la valeur du champ. Voir <a href="./../development/sections-widgets.html#liens-et-boutons-cta">Liens et boutons CTA</a>.</p><h3 id="mon-header-footer-scaffolde-n-affiche-aucun-lien-de-navigation" tabindex="-1">Mon Header/Footer scaffoldé n&#39;affiche aucun lien de navigation <a class="header-anchor" href="#mon-header-footer-scaffolde-n-affiche-aucun-lien-de-navigation" aria-label="Permalink to &quot;Mon Header/Footer scaffoldé n&#39;affiche aucun lien de navigation&quot;">​</a></h3><p>Un composant Header/Footer ne fait qu&#39;afficher les items renvoyés par <code>getMenuItemsByLocation(&#39;header&#39;|&#39;footer&#39;)</code> — s&#39;il n&#39;existe encore aucune location, menu ou item créés en base, la liste est naturellement vide. Voir <a href="./../development/menus.html">Menus</a>.</p><h3 id="pourquoi-le-carousel-modal-accordeon-du-template-html-source-ne-fonctionne-plus-une-fois-integre" tabindex="-1">Pourquoi le carousel/modal/accordéon du template HTML source ne fonctionne plus une fois intégré ? <a class="header-anchor" href="#pourquoi-le-carousel-modal-accordeon-du-template-html-source-ne-fonctionne-plus-une-fois-integre" aria-label="Permalink to &quot;Pourquoi le carousel/modal/accordéon du template HTML source ne fonctionne plus une fois intégré ?&quot;">​</a></h3><p>Aucun script JS de plugin (Bootstrap, lightbox...) ne doit rester fonctionnel dans un composant final — ces comportements sont ré-implémentés nativement (Vue/React). L&#39;attribut <code>data-bs-toggle</code> peut rester pour le style CSS, mais plus pour le comportement. Voir <a href="./../development/sections-widgets.html#comportements-interactifs">Comportements interactifs</a>.</p><h3 id="comment-choisir-entre-text-i18n-text-et-i18n-editor-pour-un-champ" tabindex="-1">Comment choisir entre <code>text</code>, <code>i18n-text</code> et <code>i18n-editor</code> pour un champ ? <a class="header-anchor" href="#comment-choisir-entre-text-i18n-text-et-i18n-editor-pour-un-champ" aria-label="Permalink to &quot;Comment choisir entre `text`, `i18n-text` et `i18n-editor` pour un champ ?&quot;">​</a></h3><p><code>text</code> pour tout ce qui n&#39;est pas traduisible (URL, nom propre) ; <code>i18n-text</code> pour une chaîne traduisible courte (titre, label) ; <code>i18n-editor</code> pour toute description, quelle que soit sa longueur — jamais <code>i18n-textarea</code>. Voir <a href="./../development/sections-widgets.html#types-de-champs">Types de champs</a>.</p><h3 id="une-meme-section-peut-elle-apparaitre-deux-fois-sur-une-page-avec-un-contenu-different" tabindex="-1">Une même section peut-elle apparaître deux fois sur une page avec un contenu différent ? <a class="header-anchor" href="#une-meme-section-peut-elle-apparaitre-deux-fois-sur-une-page-avec-un-contenu-different" aria-label="Permalink to &quot;Une même section peut-elle apparaître deux fois sur une page avec un contenu différent ?&quot;">​</a></h3><p>Oui, via un <code>--link-id</code> distinct à chaque attachement (<code>creopse page attach-section home Hero --link-id top</code>, <code>--link-id bottom</code>...). Voir <a href="./../development/pages.html#attacher-des-sections">Attacher des sections</a>.</p><h2 id="modeles-de-contenu-permaliens" tabindex="-1">Modèles de contenu &amp; permaliens <a class="header-anchor" href="#modeles-de-contenu-permaliens" aria-label="Permalink to &quot;Modèles de contenu &amp; permaliens&quot;">​</a></h2><h3 id="quand-utiliser-un-modele-de-contenu-plutot-qu-une-collection-de-section" tabindex="-1">Quand utiliser un modèle de contenu plutôt qu&#39;une collection de section ? <a class="header-anchor" href="#quand-utiliser-un-modele-de-contenu-plutot-qu-une-collection-de-section" aria-label="Permalink to &quot;Quand utiliser un modèle de contenu plutôt qu&#39;une collection de section ?&quot;">​</a></h3><p>Dès qu&#39;un contenu suit un pattern « liste + détail » (chaque élément a sa propre page de détail) — Services, Projets, Équipe... Une simple collection de section suffit pour un contenu qui reste toujours affiché en bloc sur la même page. Voir <a href="./../development/content-models.html#quand-utiliser-un-modele-de-contenu">Quand utiliser un modèle de contenu</a>.</p><h3 id="j-ai-mis-has-permalink-true-sur-mon-modele-mais-la-page-de-detail-renvoie-une-404" tabindex="-1">J&#39;ai mis <code>--has-permalink true</code> sur mon modèle mais la page de détail renvoie une 404 <a class="header-anchor" href="#j-ai-mis-has-permalink-true-sur-mon-modele-mais-la-page-de-detail-renvoie-une-404" aria-label="Permalink to &quot;J&#39;ai mis `--has-permalink true` sur mon modèle mais la page de détail renvoie une 404&quot;">​</a></h3><p>Ce flag marque seulement le modèle comme éligible — il ne câble aucune route. Il faut créer le permalien séparément avec <code>creopse permalink add</code>. Voir <a href="./../development/permalinks.html">Permaliens</a>.</p><h3 id="comment-choisir-entre-resoudre-un-permalien-par-id-ou-par-slug" tabindex="-1">Comment choisir entre résoudre un permalien par <code>id</code> ou par <code>slug</code> ? <a class="header-anchor" href="#comment-choisir-entre-resoudre-un-permalien-par-id-ou-par-slug" aria-label="Permalink to &quot;Comment choisir entre résoudre un permalien par `id` ou par `slug` ?&quot;">​</a></h3><p><code>id</code> par défaut pour un modèle de contenu personnalisé, sauf si un champ dédié (ex. <code>slug</code>) existe réellement dans sa structure. Pour les articles/catégories/tags de news (structure native), <code>slug</code> est l&#39;usage idiomatique. Voir <a href="./../development/permalinks.html#choix-de-content-param">Permaliens</a>.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><h3 id="comment-garder-un-footer-ou-un-header-strictement-identique-sur-toutes-les-pages" tabindex="-1">Comment garder un Footer (ou un Header) strictement identique sur toutes les pages ? <a class="header-anchor" href="#comment-garder-un-footer-ou-un-header-strictement-identique-sur-toutes-les-pages" aria-label="Permalink to &quot;Comment garder un Footer (ou un Header) strictement identique sur toutes les pages ?&quot;">​</a></h3><p>Avec <code>creopse page set-section-source</code>, qui fait pointer une instance de section vers la source de données d&#39;une autre — plutôt que de dupliquer manuellement les mêmes données sur chaque page. Voir <a href="./../development/pages.html#partager-les-donnees-entre-pages">Partager les données entre pages</a>.</p><h3 id="quelle-difference-entre-desactiver-une-section-et-la-detacher" tabindex="-1">Quelle différence entre désactiver une section et la détacher ? <a class="header-anchor" href="#quelle-difference-entre-desactiver-une-section-et-la-detacher" aria-label="Permalink to &quot;Quelle différence entre désactiver une section et la détacher ?&quot;">​</a></h3><p><code>toggle-section-status</code> désactive une instance sans la retirer (utile pour une section prête mais pas encore publiée) ; <code>detach-section</code> la retire définitivement — à réserver aux erreurs d&#39;attachement. Voir <a href="./../development/pages.html#activer-desactiver-ou-detacher-une-instance">Pages</a>.</p><h2 id="stack-vue-vs-react" tabindex="-1">Stack Vue vs React <a class="header-anchor" href="#stack-vue-vs-react" aria-label="Permalink to &quot;Stack Vue vs React&quot;">​</a></h2><h3 id="comment-choisir-entre-vue-et-react-et-peut-on-changer-apres-coup" tabindex="-1">Comment choisir entre Vue et React, et peut-on changer après coup ? <a class="header-anchor" href="#comment-choisir-entre-vue-et-react-et-peut-on-changer-apres-coup" aria-label="Permalink to &quot;Comment choisir entre Vue et React, et peut-on changer après coup ?&quot;">​</a></h3><p>Le choix se fait à l&#39;installation (<code>creopse install -t vue|react</code>) et détermine toute la suite du développement (conventions, composants). Il n&#39;y a pas de bascule automatique une fois le projet lancé — voir <a href="./../development/template-structure.html">Structure du template</a>.</p><h3 id="la-couverture-de-la-documentation-est-elle-la-meme-pour-vue-et-react" tabindex="-1">La couverture de la documentation est-elle la même pour Vue et React ? <a class="header-anchor" href="#la-couverture-de-la-documentation-est-elle-la-meme-pour-vue-et-react" aria-label="Permalink to &quot;La couverture de la documentation est-elle la même pour Vue et React ?&quot;">​</a></h3><p>Les deux stacks partagent la même API (<code>@creopse/utils</code>, mêmes composables/hooks nommés à l&#39;identique), mais les patterns Vue s&#39;appuient sur davantage d&#39;exemples réels que ceux React à ce stade — voir <a href="./../development/sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="divers" tabindex="-1">Divers <a class="header-anchor" href="#divers" aria-label="Permalink to &quot;Divers&quot;">​</a></h2><h3 id="ou-sont-documentees-toutes-les-commandes-cli-disponibles" tabindex="-1">Où sont documentées toutes les commandes CLI disponibles ? <a class="header-anchor" href="#ou-sont-documentees-toutes-les-commandes-cli-disponibles" aria-label="Permalink to &quot;Où sont documentées toutes les commandes CLI disponibles ?&quot;">​</a></h3><p>Dans la <a href="./cli.html">référence CLI</a>, qui couvre <code>section</code>, <code>widget</code>, <code>page</code>, <code>content-model</code>, <code>permalink</code>, <code>menu</code>, <code>media</code> et <code>base-info</code>.</p><h3 id="comment-mettre-a-jour-creopse-vers-une-nouvelle-version" tabindex="-1">Comment mettre à jour Creopse vers une nouvelle version ? <a class="header-anchor" href="#comment-mettre-a-jour-creopse-vers-une-nouvelle-version" aria-label="Permalink to &quot;Comment mettre à jour Creopse vers une nouvelle version ?&quot;">​</a></h3><p>Voir <a href="./../development/updating-creopse.html">Mise à jour de Creopse</a>.</p>',35)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
